//! 将阶段门禁绑定到 Git 已跟踪及非忽略新增文件的实际字节。

use sha2::{Digest, Sha256};
use std::ffi::{OsStr, OsString};
use std::fs::{self, File};
use std::io::{Read, Write};
use std::path::{Component, Path, PathBuf};
use std::process::Command;

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Entry {
    pub path_hex: String,
    pub display: String,
    pub kind: &'static str,
    pub sha256: Option<String>,
    pub mode: Option<u32>,
}

#[derive(Clone, Debug)]
pub struct Snapshot {
    pub digest: String,
    pub entries: Vec<Entry>,
}

impl Snapshot {
    pub fn to_json(&self) -> serde_json::Value {
        serde_json::json!({
            "schema": "lingxi-candidate-source-v1",
            "digestSha256": self.digest,
            "fileCount": self.entries.len(),
            "pathEncoding": if cfg!(unix) { "unix-bytes-hex" } else { "windows-utf8-hex" },
            "entries": self.entries.iter().map(|e| serde_json::json!({
                "pathBytesHex": e.path_hex,
                "display": e.display,
                "kind": e.kind,
                "sha256": e.sha256,
                "mode": e.mode,
            })).collect::<Vec<_>>(),
        })
    }
}

#[derive(Clone, Debug)]
pub struct Scope {
    excluded_relative: Option<PathBuf>,
    output_files: Vec<PathBuf>,
    #[cfg(unix)]
    output_identities: Vec<(u64, u64)>,
}

impl Scope {
    pub fn new(root: &Path, evidence_root: &Path) -> Result<Self, String> {
        let root = root
            .canonicalize()
            .map_err(|e| format!("cannot canonicalize repo root: {e}"))?;
        reject_symlink_components(evidence_root)?;
        // 只排除调用者给出的字面输出路径；解析后的链接目标绝不能变成排除范围。
        let evidence = normalize_evidence_path(evidence_root)?;
        let excluded_relative = evidence.strip_prefix(&root).ok().map(Path::to_path_buf);
        if excluded_relative
            .as_ref()
            .is_some_and(|p| p.as_os_str().is_empty())
        {
            return Err(
                "--evidence cannot be the repo root: it would exclude the entire candidate".into(),
            );
        }
        if let Some(relative) = &excluded_relative {
            reject_tracked_output(&root, relative)?;
        }
        // 只识别真实 fd 对应的精确文件；祖先日志的父目录不因此变成输出目录。
        let discovery = Command::new("python3")
            .args([
                "-c",
                include_str!("../../../../scripts/rust-tauri/run_output_sinks.py"),
            ])
            .arg(&root)
            .arg(&evidence)
            .arg("--files")
            .output()
            .map_err(|e| format!("cannot discover run-output sinks: {e}"))?;
        if !discovery.status.success() {
            return Err(format!(
                "run-output discovery failed: {}",
                String::from_utf8_lossy(&discovery.stderr)
            ));
        }
        let mut output_files = Vec::new();
        for row in discovery
            .stdout
            .split(|b| *b == b'\n')
            .filter(|row| !row.is_empty())
        {
            if row == b"DISCOVERY-UNAVAILABLE" {
                return Err(
                    "run-output discovery unavailable; refusing incomplete candidate binding"
                        .into(),
                );
            }
            let raw = row.strip_prefix(b"FILE ").ok_or_else(|| {
                format!(
                    "invalid or tracked run-output sink: {}",
                    String::from_utf8_lossy(row)
                )
            })?;
            let relative = path_from_git(raw)?;
            if relative
                .components()
                .any(|c| !matches!(c, Component::Normal(_)))
            {
                return Err("run-output sink is not a plain repository-relative file".into());
            }
            reject_symlink_components(&root.join(&relative))?;
            reject_tracked_output(&root, &relative)?;
            output_files.push(relative);
        }
        output_files.sort();
        output_files.dedup();
        #[cfg(unix)]
        let output_identities = output_files
            .iter()
            .map(|relative| {
                use std::os::unix::fs::MetadataExt;
                let metadata = fs::symlink_metadata(root.join(relative))
                    .map_err(|e| format!("cannot identify output sink: {e}"))?;
                Ok((metadata.dev(), metadata.ino()))
            })
            .collect::<Result<Vec<_>, String>>()?;
        Ok(Self {
            excluded_relative,
            output_files,
            #[cfg(unix)]
            output_identities,
        })
    }

    pub fn exclusion_json(&self) -> serde_json::Value {
        serde_json::json!({
            "evidenceOutputRelativePath": self.excluded_relative.as_ref().map(|p| p.to_string_lossy().to_string()),
            "evidenceOutputPathBytesHex": self.excluded_relative.as_ref().map(|p| hex(&os_bytes(p.as_os_str()))),
            "runOutputFiles": self.output_files.iter().map(|p| serde_json::json!({
                "relativePath": p.to_string_lossy(), "pathBytesHex": hex(&os_bytes(p.as_os_str())), "kind": "FILE"
            })).collect::<Vec<_>>(),
            "policy": "This invocation's fresh --evidence subtree and exact real OS fd stdout/stderr files of this process and its ancestors are excluded. No ancestor sink directory is excluded. The set is fixed before binding; other tracked and non-ignored untracked paths stay bound.",
        })
    }

    pub fn snapshot(&self, root: &Path) -> Result<Snapshot, String> {
        if let Some(relative) = &self.excluded_relative {
            reject_symlink_components(&root.join(relative))?;
            reject_tracked_output(root, relative)?;
        }
        for (index, relative) in self.output_files.iter().enumerate() {
            reject_symlink_components(&root.join(relative))?;
            reject_tracked_output(root, relative)?;
            let metadata = fs::symlink_metadata(root.join(relative))
                .map_err(|e| format!("cannot inspect run-output sink: {e}"))?;
            #[cfg(unix)]
            {
                use std::os::unix::fs::MetadataExt;
                if (metadata.dev(), metadata.ino()) != self.output_identities[index] {
                    return Err(format!(
                        "run-output sink {} was replaced after binding",
                        relative.display()
                    ));
                }
            }
            #[cfg(windows)]
            let _ = index;
            if !metadata.is_file() {
                return Err(format!(
                    "run-output sink {} disappeared or changed type",
                    relative.display()
                ));
            }
        }
        let output = Command::new("git")
            .args([
                "ls-files",
                "--cached",
                "--others",
                "--exclude-standard",
                "-z",
                "--",
            ])
            .current_dir(root)
            .output()
            .map_err(|e| format!("cannot run git ls-files for candidate binding: {e}"))?;
        if !output.status.success() {
            return Err(format!(
                "git ls-files for candidate binding failed: {}",
                String::from_utf8_lossy(&output.stderr)
            ));
        }
        let mut paths = Vec::<Vec<u8>>::new();
        for raw in output.stdout.split(|b| *b == 0).filter(|p| !p.is_empty()) {
            paths.push(raw.to_vec());
        }
        paths.sort();
        paths.dedup();
        let mut entries = Vec::with_capacity(paths.len());
        for raw in paths {
            let relative = path_from_git(&raw)?;
            if relative
                .components()
                .any(|c| !matches!(c, Component::Normal(_)))
            {
                return Err(format!(
                    "git candidate path is not a plain relative path: {}",
                    hex(&raw)
                ));
            }
            if self
                .excluded_relative
                .as_ref()
                .is_some_and(|p| relative.starts_with(p))
                || self.output_files.contains(&relative)
            {
                continue;
            }
            let (sha256, mode) = hash_candidate_file(root, &relative)?;
            entries.push(Entry {
                path_hex: hex(&raw),
                display: relative.to_string_lossy().into_owned(),
                kind: "file",
                sha256: Some(sha256),
                mode,
            });
        }
        let mut hasher = Sha256::new();
        hasher.update(b"lingxi-candidate-source-v1\0");
        for entry in &entries {
            for value in [
                &entry.path_hex,
                entry.kind,
                entry.sha256.as_deref().unwrap_or(""),
                &entry.mode.map(|m| m.to_string()).unwrap_or_default(),
            ] {
                hasher.update((value.len() as u64).to_be_bytes());
                hasher.update(value.as_bytes());
            }
        }
        Ok(Snapshot {
            digest: hex(&hasher.finalize()),
            entries,
        })
    }
}

fn reject_tracked_output(root: &Path, relative: &Path) -> Result<(), String> {
    let query = Command::new("git")
        .args(["--literal-pathspecs", "ls-files", "-z", "--"])
        .arg(relative)
        .current_dir(root)
        .output()
        .map_err(|e| format!("cannot inspect output ownership: {e}"))?;
    if !query.status.success() || !query.stdout.is_empty() {
        return Err(format!(
            "run-output path {} covers tracked candidate content",
            relative.display()
        ));
    }
    Ok(())
}

#[cfg(unix)]
fn hash_candidate_file(root: &Path, relative: &Path) -> Result<(String, Option<u32>), String> {
    use std::ffi::CString;
    use std::os::fd::{AsRawFd, FromRawFd};
    use std::os::unix::fs::MetadataExt;

//! 拒绝拿旧 xtask 可执行文件评估已变化的门禁源码或内嵌阶段图。

use sha2::{Digest, Sha256};
use std::collections::BTreeSet;
use std::fs;
use std::path::{Path, PathBuf};

const EMBEDDED: &[(&str, &[u8])] = &[
    (
        "scripts/rust-tauri/run_output_sinks.py",
        include_bytes!("../../../../scripts/rust-tauri/run_output_sinks.py"),
    ),
    ("rust/crates/xtask/src/main.rs", include_bytes!("main.rs")),
    (
        "rust/crates/xtask/src/verify.rs",
        include_bytes!("verify.rs"),
    ),
    (
        "rust/crates/xtask/src/stage_map.rs",
        include_bytes!("stage_map.rs"),
    ),
    (
        "rust/crates/xtask/src/candidate.rs",
        include_bytes!("candidate.rs"),
    ),
    (
        "rust/crates/xtask/src/runner_identity.rs",
        include_bytes!("runner_identity.rs"),
    ),
    (
        "rust/crates/xtask/src/stage_maps/R02.json",
        include_bytes!("stage_maps/R02.json"),
    ),
    (
        "rust/crates/xtask/src/stage_maps/R03.json",
        include_bytes!("stage_maps/R03.json"),
    ),
    (
        "rust/crates/xtask/src/stage_maps/R04.json",
        include_bytes!("stage_maps/R04.json"),
    ),
    (
        "rust/crates/xtask/src/stage_maps/R05.json",
        include_bytes!("stage_maps/R05.json"),
    ),
    (
        "rust/crates/xtask/Cargo.toml",
        include_bytes!("../Cargo.toml"),
    ),
    ("rust/Cargo.toml", include_bytes!("../../../Cargo.toml")),
    (
        "rust-toolchain.toml",
        include_bytes!("../../../../rust-toolchain.toml"),
    ),
];

const SOURCE_INVENTORY: &[&str] = &[
    "main.rs",
    "verify.rs",
    "stage_map.rs",
    "candidate.rs",
    "runner_identity.rs",
    "stage_maps/R02.json",
    "stage_maps/R03.json",
    "stage_maps/R04.json",
    "stage_maps/R05.json",
    "verify/runner_tests.rs",
    "candidate/tests.rs",
];

pub fn check(root: &Path) -> Result<serde_json::Value, String> {
    let mut records = Vec::with_capacity(EMBEDDED.len());
    for (relative, compiled) in EMBEDDED {
        let path = root.join(relative);
        let metadata = fs::symlink_metadata(&path).map_err(|e| {
            format!(
                "runner source {} is missing or inaccessible: {e}",
                path.display()
            )
        })?;
        if !metadata.is_file() || metadata.file_type().is_symlink() {
            return Err(format!(
                "runner source {} is no longer a regular file",
                path.display()
            ));
        }
        let disk = fs::read(&path)
            .map_err(|e| format!("cannot read runner source {}: {e}", path.display()))?;
        if disk != *compiled {
            return Err(format!(
                "stale xtask binary: compiled {:?} differs from current disk bytes; rebuild this runner from the candidate before stage verification",
                relative
            ));
        }
        records.push(serde_json::json!({
            "path": relative,
            "compiledAndDiskSha256": Sha256::digest(compiled).iter().map(|byte| format!("{byte:02x}")).collect::<String>(),
        }));
    }
    let source_root = root.join("rust/crates/xtask/src");
    let mut actual = BTreeSet::new();
    collect_source_files(&source_root, &source_root, &mut actual)?;
    let expected: BTreeSet<String> = SOURCE_INVENTORY.iter().map(|s| s.to_string()).collect();
    if actual != expected {
        return Err(format!(
            "stale xtask binary: source inventory differs; added={:?}, missing={:?}",
            actual.difference(&expected).collect::<Vec<_>>(),
            expected.difference(&actual).collect::<Vec<_>>()
        ));
    }
    Ok(serde_json::json!({
        "schema": "lingxi-xtask-runner-source-v1",
        "status": "PASS",
        "compiledSourceFiles": records,
        "sourceInventory": actual,
        "note": "The executable's embedded implementation and R02 stage map exactly match current disk bytes before any registered command runs.",
    }))
}

fn collect_source_files(base: &Path, dir: &Path, out: &mut BTreeSet<String>) -> Result<(), String> {
    for entry in fs::read_dir(dir)
        .map_err(|e| format!("cannot list runner sources {}: {e}", dir.display()))?
    {
        let entry = entry.map_err(|e| format!("cannot list runner source entry: {e}"))?;
        let path: PathBuf = entry.path();
        let metadata = fs::symlink_metadata(&path)
            .map_err(|e| format!("cannot inspect runner source {}: {e}", path.display()))?;
        if metadata.file_type().is_symlink() {
            return Err(format!(
                "runner source tree contains symlink {}",
                path.display()
            ));
        }
        if metadata.is_dir() {
            collect_source_files(base, &path, out)?;
        } else if path
            .extension()
            .is_some_and(|ext| ext == "rs" || ext == "json")
        {
            let relative = path
                .strip_prefix(base)
                .map_err(|e| format!("runner source path error: {e}"))?;
            out.insert(relative.to_string_lossy().replace('\\', "/"));
        }
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::time::{SystemTime, UNIX_EPOCH};

    #[test]
    fn old_embedded_stage_map_rejects_new_disk_map() {
        let stamp = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        let root = std::env::temp_dir().join(format!(
            "lingxi-runner-identity-{}-{stamp}",
            std::process::id()
        ));
        for (relative, bytes) in EMBEDDED {
            let path = root.join(relative);
            fs::create_dir_all(path.parent().unwrap()).unwrap();
            fs::write(path, bytes).unwrap();
        }
        for relative in SOURCE_INVENTORY {
            let path = root.join("rust/crates/xtask/src").join(relative);
            if !path.exists() {
                fs::create_dir_all(path.parent().unwrap()).unwrap();
                fs::write(path, b"test only").unwrap();
            }
        }
        assert_eq!(check(&root).unwrap()["status"], "PASS");
        let discovery_path = root.join("scripts/rust-tauri/run_output_sinks.py");
        let discovery_bytes = fs::read(&discovery_path).unwrap();
        fs::write(&discovery_path, b"changed discovery implementation").unwrap();
        assert!(check(&root).unwrap_err().contains("run_output_sinks.py"));
        fs::write(discovery_path, discovery_bytes).unwrap();
        fs::write(
            root.join("rust/crates/xtask/src/stage_maps/R02.json"),
            b"{\"new\":true}",
        )
        .unwrap();
        let err = check(&root).unwrap_err();
        assert!(
            err.contains("stale xtask binary") && err.contains("R02.json"),
